import{_ as a,o,c as r,a2 as t}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),n={name:"faq.md"};function s(i,e,d,l,c,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="what-is-arkel" tabindex="-1">What is Arkel? <a class="header-anchor" href="#what-is-arkel" aria-label="Permalink to &quot;What is Arkel?&quot;">​</a></h2><p>Arkel is a community powered object storage network. Node operators contribute disk and will earn credit, users pay to store encrypted, erasure-coded blobs.</p><h2 id="how-is-my-data-secured" tabindex="-1">How is my data secured? <a class="header-anchor" href="#how-is-my-data-secured" aria-label="Permalink to &quot;How is my data secured?&quot;">​</a></h2><p>Objects are encrypted on your machine with XChaCha20-Poly1305 before they are erasure-coded, so storage nodes only ever hold ciphertext. The reconstructed object is verified against a BLAKE3 object hash on download.</p><h2 id="what-happens-if-a-storage-node-goes-offline" tabindex="-1">What happens if a storage node goes offline? <a class="header-anchor" href="#what-happens-if-a-storage-node-goes-offline" aria-label="Permalink to &quot;What happens if a storage node goes offline?&quot;">​</a></h2><p>Arkel and most object storage solutions use Erasure coding. This technique splits each object into <code>k</code> data shards and <code>m</code> parity shards Reads need only <code>k</code> shards, so the object survives losing up to <code>m</code> nodes.</p><h2 id="do-i-need-to-run-my-own-node-to-use-arkel" tabindex="-1">Do I need to run my own node to use Arkel? <a class="header-anchor" href="#do-i-need-to-run-my-own-node-to-use-arkel" aria-label="Permalink to &quot;Do I need to run my own node to use Arkel?&quot;">​</a></h2><p>No. Storage operators run nodes and earn credit. If you simply want to store and retrieve objects, users can pay for storage. See <a href="/contribute">Contribute</a> if you want to run a node.</p><h2 id="when-can-i-get-paid-to-run-a-node" tabindex="-1">When can I get paid to run a node? <a class="header-anchor" href="#when-can-i-get-paid-to-run-a-node" aria-label="Permalink to &quot;When can I get paid to run a node?&quot;">​</a></h2><p>Soon, we are actively testing the network and welcome contributors. The contribution economy and payouts are being built.</p><h2 id="is-arkel-s3-compatible" tabindex="-1">Is Arkel S3-compatible? <a class="header-anchor" href="#is-arkel-s3-compatible" aria-label="Permalink to &quot;Is Arkel S3-compatible?&quot;">​</a></h2><p>Not yet. An S3-compatible gateway is on the <a href="/roadmap">roadmap</a> so regular tools like rclone, restic, and any system using s3 compatible can talk to Arkel. Currenly you can use the <a href="/cli"><code>arkel</code> CLI</a>.</p><h2 id="can-storage-operators-read-my-files" tabindex="-1">Can storage operators read my files? <a class="header-anchor" href="#can-storage-operators-read-my-files" aria-label="Permalink to &quot;Can storage operators read my files?&quot;">​</a></h2><p>No. They hold only encrypted shards, and no single node holds enough shards to reconstruct an object. Your master key never leaves your machine.</p><h2 id="what-if-i-lose-my-key" tabindex="-1">What if I lose my key? <a class="header-anchor" href="#what-if-i-lose-my-key" aria-label="Permalink to &quot;What if I lose my key?&quot;">​</a></h2><p>There is no server-side key escrow or recovery. If you lose your master key, the data is unrecoverable. Treat key backup as essential.</p><h2 id="is-arkel-ready-for-production" tabindex="-1">Is Arkel ready for production? <a class="header-anchor" href="#is-arkel-ready-for-production" aria-label="Permalink to &quot;Is Arkel ready for production?&quot;">​</a></h2><p>It is in early alpha and under active development. The core network works and you can use it today. We recommend using Arkel as an additional layer of backup. Post Beta, we aim to be a complete replacement for your object storage needs.</p>',19)])])}const y=a(n,[["render",s]]);export{p as __pageData,y as default};
